import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, "..");
const vendorDir = path.join(rootDir, "vendor", "unicornstudio");
const outputFile = path.join(rootDir, "src", "shared", "sdk-bundle.ts");

const bundledScripts = [
  {
    id: "core",
    relativePath: "unicornStudio.umd.js",
  },
  {
    id: "model-renderer",
    relativePath: "extensions/model-renderer.js",
  },
  {
    id: "three-bundle",
    relativePath: "extensions/three-bundle.js",
  },
];

async function readBundledScript(relativePath) {
  const absolutePath = path.join(vendorDir, relativePath);

  try {
    return await fs.readFile(absolutePath, "utf8");
  } catch {
    return "";
  }
}

async function main() {
  const scripts = await Promise.all(
    bundledScripts.map(async (script) => ({
      ...script,
      content: await readBundledScript(script.relativePath),
    })),
  );

  const available = scripts.every((script) => script.content.trim().length > 0);

  const fileContents = `/**
 * Generated by \`npm run sync-sdk\`.
 * Do not edit this file manually.
 */
export interface BundledUnicornStudioScript {
  id: string;
  relativePath: string;
  content: string;
}

export interface BundledUnicornStudioSdk {
  available: boolean;
  scripts: BundledUnicornStudioScript[];
}

export const BUNDLED_UNICORN_SDK: BundledUnicornStudioSdk = ${JSON.stringify(
    { available, scripts },
    null,
    2,
  )} as const;
`;

  await fs.writeFile(outputFile, fileContents);
  process.stdout.write(
    available
      ? "Bundled Unicorn Studio SDK synced.\n"
      : "Bundled Unicorn Studio SDK files are incomplete; wrote placeholder bundle.\n",
  );
}

await main();
